document.addEventListener('DOMContentLoaded', () => {
    const width = 800;
    const height = 600;
    const margin = { top: 20, right: 20, bottom: 20, left: 20 };

    const svg = d3.select('#chart')
        .append('svg')
        .attr('width', width)
        .attr('height', height)
        .attr('viewBox', [0, 0, width, height]);

    const tooltip = d3.select('#tooltip');

    d3.csv('data/stock-descriptions.csv').then(data => {
        // Data cleaning
        data.forEach(d => {
            d.marketCap = d.marketCap ? +d.marketCap : 0;
            d.isETF = d.sector === 'ETF';
        });

        // Sort data for determinism
        data.sort((a, b) => d3.ascending(a.ticker, b.ticker));

        const sectors = Array.from(new Set(data.map(d => d.sector))).sort();
        const colorScale = d3.scaleOrdinal()
            .domain(sectors)
            .range(d3.schemeCategory10);

        // Bubble size scale
        const maxCap = d3.max(data, d => d.marketCap);
        const radiusScale = d3.scaleSqrt()
            .domain([0, maxCap])
            .range([5, 60]);

        const getRadius = d => d.isETF ? 25 : radiusScale(d.marketCap);

        // Position clusters
        const sectorCenters = {};
        const angleStep = (2 * Math.PI) / sectors.length;
        sectors.forEach((sector, i) => {
            const angle = i * angleStep;
            const r = 180;
            sectorCenters[sector] = {
                x: width / 2 + r * Math.cos(angle),
                y: height / 2 + r * Math.sin(angle)
            };
        });

        // Legend
        const legendContainer = d3.select('#legend');
        sectors.forEach(sector => {
            const item = legendContainer.append('div').attr('class', 'legend-item');
            item.append('div')
                .attr('class', 'legend-color')
                .style('background-color', colorScale(sector));
            item.append('span').text(sector);
        });

        // Table
        const tbody = d3.select('#stock-table tbody');
        const rows = tbody.selectAll('tr')
            .data(data)
            .enter()
            .append('tr')
            .attr('id', d => `row-${d.ticker}`)
            .on('click', function(event, d) {
                highlightStock(d.ticker);
            });

        rows.append('td').text(d => d.ticker);
        rows.append('td').text(d => d['full name']);
        rows.append('td').text(d => d.sector);
        rows.append('td').text(d => formatMarketCap(d.marketCap));

        // Simulation
        const simulation = d3.forceSimulation(data)
            .force('x', d3.forceX(d => sectorCenters[d.sector].x).strength(0.2))
            .force('y', d3.forceY(d => sectorCenters[d.sector].y).strength(0.2))
            .force('collide', d3.forceCollide(d => getRadius(d) + 2))
            .force('center', d3.forceCenter(width / 2, height / 2).strength(0.01))
            .stop();

        // Run simulation for a fixed number of ticks for determinism
        for (let i = 0; i < 300; ++i) simulation.tick();

        const node = svg.append('g')
            .selectAll('g')
            .data(data)
            .join('g')
            .attr('class', 'node')
            .attr('transform', d => `translate(${d.x},${d.y})`)
            .on('click', function(event, d) {
                highlightStock(d.ticker);
            })
            .on('mouseover', function(event, d) {
                if (d.isETF) return;
                tooltip.style('opacity', 1)
                    .html(`<strong>${d.ticker}</strong><br/>${d['full name']}<br/>Sector: ${d.sector}`)
                    .style('left', (event.pageX + 10) + 'px')
                    .style('top', (event.pageY - 10) + 'px');
            })
            .on('mousemove', function(event) {
                tooltip.style('left', (event.pageX + 10) + 'px')
                    .style('top', (event.pageY - 10) + 'px');
            })
            .on('mouseout', function() {
                tooltip.style('opacity', 0);
            });

        node.append('circle')
            .attr('id', d => `circle-${d.ticker}`)
            .attr('r', d => getRadius(d))
            .attr('fill', d => colorScale(d.sector));

        node.append('text')
            .attr('class', 'label')
            .attr('dy', '.3em')
            .text(d => d.ticker)
            .style('font-size', d => Math.min(getRadius(d) / 2, 12) + 'px');

        function highlightStock(ticker) {
            // Reset
            d3.selectAll('tr').classed('highlighted', false);
            d3.selectAll('circle').classed('highlighted', false);

            // Highlight circle
            const circle = d3.select(`#circle-${ticker}`);
            circle.classed('highlighted', true);

            // Highlight table row and scroll to it
            const row = d3.select(`#row-${ticker}`);
            row.classed('highlighted', true);
            row.node().scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        }
    });

    function formatMarketCap(d) {
        if (!d || d === 0) return "N/A";
        if (d >= 1e12) return (d / 1e12).toFixed(2) + "T";
        if (d >= 1e9) return (d / 1e9).toFixed(2) + "B";
        if (d >= 1e6) return (d / 1e6).toFixed(2) + "M";
        return d.toLocaleString();
    }
});

